            assertTrue(Thread.currentThread().isInterrupted());
        } finally {
            Thread.interrupted();
        }
    }

    @Test
    public void nullService() {
        assertThrows(NullPointerException.class, () -> new BackgroundTask(new TestBudget(1, true), null, "x"));
